list_group=['_pf_chunk','_pf_collect','_pf_concat','_pf_count_by','_pf_distinct','_pf_distinct_by','_pf_drop','_pf_drop_while','_pf_exists','_pf_filter','_pf_flatten','_pf_fold','_pf_forall','_pf_group_by','_pf_indexed','_pf_init','_pf_insert_at','_pf_is_empty','_pf_iter','_pf_list_contains','_pf_map','_pf_map2','_pf_pairwise','_pf_partition','_pf_range','_pf_remove_at','_pf_replicate','_pf_rev','_pf_sort','_pf_sort_by','_pf_sort_by_desc','_pf_sort_desc','_pf_split_at','_pf_sum_by','_pf_take','_pf_take_while','_pf_unzip','_pf_update_at','_pf_windowed','_pf_zip']
prelude=['_pf_const','_pf_flip','_pf_fst','_pf_id','_pf_ignore','_pf_sign','_pf_snd']
asyncg=['_pf_Async','_pf_async_catch','_pf_async_parallel','_pf_async_race','_pf_async_sleep','_pf_async_timeout','_pf_async_to_thread','_pf_run','_pf_task_scope','_pf_task_start']
codecs=['_pf_dec_auto','_pf_dec_auto_value','_pf_enc_auto','_pf_enc_value']
groups={}
for k in h:
    if k in list_group: g=1
    elif k in prelude: g=3
    elif k in asyncg: g=5
    elif k in codecs: g=6
    elif k.startswith('_pf_dec_'): g=4
    else: g=2
    groups[k]=g
def deps(name,body):
    d=[]
    if re.search(r'\bSome\b|_None_|None_\(',body): d.append('#option')
    if re.search(r'\bOk\(|\bError\(|isinstance\(\w+, (Ok|Error)\)',body): d.append('#result')
    if '_Exception(' in body: d.append('#exception')
    for imp in ['functools','itertools','json','asyncio','contextvars','dataclasses','keyword','math']:
        if re.search(r'\b'+imp+r'\.',body): d.append('@'+imp)
    for other in h:
        if other!=name and re.search(r'\b'+re.escape(other)+r'\b',body): d.append(other)
    if '_pf_scope' in body: d.append('_pf_scope')
    return d
out=["// Runtime helper snippets emitted on demand, with their dependencies.\n",
     "// group: 1 list, 2 modules, 3 prelude, 4 decoders, 5 async, 6 codecs\n\n",
     "pub struct Helper {\n    pub name: &'static str,\n    pub group: u8,\n    pub deps: &'static [&'static str],\n    pub text: &'static str,\n}\n\n",
     "pub const HELPERS: &[Helper] = &[\n"]
def rs(s): return s.replace('\\','\\\\').replace('"','\\"')
for k in sorted(h):
    body=h[k]
    out.append(f'    Helper {{ name: "{k}", group: {groups[k]}, deps: &[{", ".join(chr(34)+x+chr(34) for x in deps(k,body))}], text: "{rs(body)}" }},\n')
out.append('    Helper { name: "_pf_scope", group: 5, deps: &["@contextvars"], text: "_pf_scope = contextvars.ContextVar(\\"_pf_scope\\")" },\n')
out.append("];\n")
open('/workspace/src/runtime.rs','w').write(''.join(out))
for k in ['_pf_task_start','_pf_dec_auto','_pf_enc_value','_pf_seq_unfold','_pf_option_to_result','_pf_dec_nullable','_pf_async_sleep']:
    print(k, deps(k,h[k]))
EOF
