// Computation expressions and active-pattern cases.

use crate::ast::*;
use crate::check_expr::*;
use crate::diag::Diag;
use crate::infer::*;
use crate::source::Span;
use crate::types::*;

type R<T> = Result<T, Diag>;

#[derive(Clone, Copy, PartialEq)]
enum CeKind {
    Async,
    Seq,
    Result,
    Option,
}

impl Checker {
    pub fn infer_ce(&mut self, path: &[String], name: &str, items: &[CeStmt], span: Span) -> R<Ty> {
        let kind = if path.is_empty() {
            match name {
                "async" => Some(CeKind::Async),
                "seq" => Some(CeKind::Seq),
                "result" => Some(CeKind::Result),
                "option" => Some(CeKind::Option),
                _ => None,
            }
        } else {
            None
        };
        let Some(kind) = kind else {
            return self.infer_user_ce(path, name, items, span);
        };
        self.push_scope();
        let r = self.infer_ce_items(kind, items, span);
        self.pop_scope();
        let t = r?;
        if kind == CeKind::Async {
            let l = self.st.label_of("async");
            self.perform(&Eff::label(l), span);
        }
        Ok(t)
    }

    fn infer_ce_items(&mut self, kind: CeKind, items: &[CeStmt], span: Span) -> R<Ty> {
        let ret = self.st.fresh();
        let err = self.st.fresh();
        let wrap = |k: CeKind, t: Ty, e: Ty| -> Ty {
            match k {
                CeKind::Async => Ty::Con("Async".into(), vec![t]),
                CeKind::Seq => Ty::Con("Seq".into(), vec![t]),
                CeKind::Result => Ty::Con("Result".into(), vec![t, e]),
                CeKind::Option => Ty::Con("Option".into(), vec![t]),
            }
        };
        let kw_name = match kind {
            CeKind::Async => "async",
            CeKind::Seq => "seq",
            CeKind::Result => "result",
            CeKind::Option => "option",
        };
        // the value of the block
        let mut has_return = false;
        self.ce_body(kind, items, &ret, &err, &mut has_return, kw_name)?;
        if kind != CeKind::Seq {
            match items.last() {
                Some(CeStmt::Return(..)) | Some(CeStmt::ReturnBang(..)) => {}
                Some(CeStmt::Let(l)) if matches!(l.pat.kind, PatKind::Wild) && kind == CeKind::Async => {
                    self.unify_at(&ret, &t_unit(), span)?;
                }
                _ => {
                    let article = if kind == CeKind::Async { "an" } else { "a" };
                    return Err(Diag::error(format!("{} `{}` block must end with `return`", article, kw_name), span));
                }
            }
        }
        Ok(wrap(kind, ret, err))
    }

    fn ce_body(&mut self, kind: CeKind, items: &[CeStmt], ret: &Ty, err: &Ty, has_return: &mut bool, kw: &str) -> R<()> {
        let wrap1 = |k: CeKind, t: Ty, e: Ty| -> Ty {
            match k {
                CeKind::Async => Ty::Con("Async".into(), vec![t]),
                CeKind::Seq => Ty::Con("Seq".into(), vec![t]),
                CeKind::Result => Ty::Con("Result".into(), vec![t, e]),
                CeKind::Option => Ty::Con("Option".into(), vec![t]),
            }
        };
        for it in items {
            match it {
                CeStmt::LetBang(p, e, sp) | CeStmt::DoBang(e, sp) if kind == CeKind::Seq => {
                    let _ = (p_dummy(), e);
                    return Err(Diag::error("only `yield`, `yield!`, `let`, and `for` are allowed in a `seq` block", *sp));
                }
                CeStmt::LetBang(p, e, _) => {
                    let te = self.infer(e)?;
                    let a = self.st.fresh();
                    let want = wrap1(kind, a.clone(), err.clone());
                    self.unify_at(&want, &te, e.span)?;
                    self.check_pat(p, &a, false)?;
                }
                CeStmt::DoBang(e, _) => {
                    let te = self.infer(e)?;
                    let a = self.st.fresh();
                    let want = wrap1(kind, a.clone(), err.clone());
                    self.unify_at(&want, &te, e.span)?;
                    self.unify_at(&a, &t_unit(), e.span)?;
                }
                CeStmt::Let(l) => {
                    self.infer_local_let(l)?;
                }
                CeStmt::Assign(n, nspan, v) => {
                    self.infer_assign(n, *nspan, v)?;
                }
                CeStmt::Return(e, sp) => {
                    if kind == CeKind::Seq {
                        return Err(Diag::error("only `yield`, `yield!`, `let`, and `for` are allowed in a `seq` block", *sp));
                    }
                    let te = self.infer(e)?;
                    self.unify_at(ret, &te, e.span)?;
                    *has_return = true;
                }
                CeStmt::ReturnBang(e, sp) => {
                    if kind == CeKind::Seq {
                        return Err(Diag::error("only `yield`, `yield!`, `let`, and `for` are allowed in a `seq` block", *sp));
                    }
                    let te = self.infer(e)?;
                    let want = wrap1(kind, ret.clone(), err.clone());
                    self.unify_at(&want, &te, e.span)?;
                    *has_return = true;
                }
                CeStmt::Yield(e, sp) => {
                    if kind != CeKind::Seq {
                        return Err(Diag::error(format!("`yield` is not allowed in a `{}` block", kw), *sp));
                    }
                    let te = self.infer(e)?;
                    self.unify_at(ret, &te, e.span)?;
                }
                CeStmt::YieldBang(e, sp) => {
                    if kind != CeKind::Seq {
                        return Err(Diag::error(format!("`yield!` is not allowed in a `{}` block", kw), *sp));
                    }
                    let te = self.infer(e)?;
                    let want = Ty::Con("Seq".into(), vec![ret.clone()]);
                    self.unify_at(&want, &te, e.span)?;
                }
                CeStmt::For(p, src, body, _) => {
                    let ts = self.infer(src)?;
                    let elem = self.st.fresh();
                    let rs = self.st.shallow(&ts);
                    let coll = match &rs {
                        Ty::Con(n, _) if n == "Seq" || n == "Set" => n.clone(),
                        _ => "List".to_string(),
                    };
                    let want = Ty::Con(coll, vec![elem.clone()]);
                    self.unify_at(&want, &ts, src.span)?;
                    self.push_scope();
                    let r = (|| -> R<()> {
                        self.check_pat(p, &elem, false)?;
                        self.ce_body(kind, body, ret, err, has_return, kw)
                    })();
                    self.pop_scope();
                    r?;
                }
            }
        }
        Ok(())
    }

    /// A user builder module: desugar to `M.bind`/`M.return_` calls.
    fn infer_user_ce(&mut self, path: &[String], name: &str, items: &[CeStmt], span: Span) -> R<Ty> {
        let mut full = path.to_vec();
        full.push(name.to_string());
        let e = desugar_user_ce(&full, items, span);
        self.infer(&e)
    }

    pub fn check_active_case(&mut self, n: &str, args: &[Pat], t: &Ty, span: Span, binds: &mut Vec<(String, Ty)>) -> Option<R<()>> {
        let tag = self.active_cases.get(n)?.clone();
        let info = self.active_patterns.get(&tag)?.clone();
        Some((|| -> R<()> {
            for a in args {
                if !matches!(a.kind, PatKind::Var(_) | PatKind::Wild) {
                    return Err(Diag::error(format!("an active-pattern case argument must be a variable or `_` (in `{}`)", n), span));
                }
            }
            let recog = self.lookup_local(&tag).map(|l| l.scheme.clone());
            let Some(recog) = recog else { return Ok(()) };
            let rt = self.st.instantiate(&recog);
            // recognizer: input -> output
            let res = self.st.fresh();
            let e = self.st.fresh_eff();
            let want = Ty::Fun(Box::new(t.clone()), e, Box::new(res.clone()));
            self.unify_at(&rt, &want, span)?;
            let res = self.st.resolve(&res);
            if info.1 {
                // partial: Option payload or bool predicate
                match &res {
                    Ty::Con(o, targs) if o == "Option" => {
                        if args.len() != 1 {
                            return Err(Diag::error(
                                format!("active pattern `{}` expects 1 argument(s) here, found {} (an Option active pattern binds its payload — add a binder)", n, args.len()),
                                span,
                            ));
                        }
                        if let PatKind::Var(v) = &args[0].kind {
                            binds.push((v.clone(), targs[0].clone()));
                        }
                    }
                    _ => {
                        if !args.is_empty() {
                            return Err(Diag::error(format!("active pattern `{}` expects 0 argument(s) here, found {}", n, args.len()), span));
                        }
                    }
                }
            } else if let Some(c) = self.ctors.get(n).cloned() {
                if c.args.len() != args.len() {
                    return Err(Diag::error(format!("constructor `{}` expects {} argument(s), found {}", n, c.args.len(), args.len()), span));
                }
                if let Ty::Con(_, targs) = &res {
                    let mut inst = Inst::default();
                    for (i, a) in targs.iter().enumerate() {
                        inst.t.insert(i, a.clone());
                    }
                    for (a, at) in args.iter().zip(c.args.iter()) {
                        if let PatKind::Var(v) = &a.kind {
                            let at = self.st.inst_ty(at, &mut inst);
                            binds.push((v.clone(), at));
                        }
                    }
                }
            }
            Ok(())
        })())
    }
}

fn p_dummy() {}

/// `M { let! x = a; return e }` => `M.bind a (fun x -> M.return_ e)`
pub fn desugar_user_ce(m: &[String], items: &[CeStmt], span: Span) -> Expr {
    let (path, name) = (m[..m.len() - 1].to_vec(), m[m.len() - 1].clone());
    let member = |mem: &str, sp: Span| -> Expr {
        let mut p = path.clone();
        p.push(name.clone());
        Expr { kind: ExprKind::Qual(p, mem.to_string(), sp), span: sp }
    };
    fn go(items: &[CeStmt], member: &dyn Fn(&str, Span) -> Expr, span: Span) -> Expr {
        let Some(first) = items.first() else {
            return Expr { kind: ExprKind::Unit, span };
        };
        let rest = &items[1..];
        let app = |f: Expr, a: Expr| -> Expr {
            let sp = f.span.to(a.span);
            Expr { kind: ExprKind::App(Box::new(f), Box::new(a)), span: sp }
        };
        match first {
            CeStmt::LetBang(p, e, sp) => {
                let k = go(rest, member, span);
                let lam = Expr { kind: ExprKind::Lambda(vec![p.clone()], Box::new(k)), span: *sp };
                app(app(member("bind", *sp), e.clone()), lam)
            }
            CeStmt::DoBang(e, sp) => {
                let k = go(rest, member, span);
                let lam = Expr { kind: ExprKind::Lambda(vec![Pat { kind: PatKind::Wild, span: *sp }], Box::new(k)), span: *sp };
                app(app(member("bind", *sp), e.clone()), lam)
            }
            CeStmt::Return(e, sp) => app(member("return_", *sp), e.clone()),
            CeStmt::ReturnBang(e, _) => e.clone(),
            CeStmt::Yield(e, sp) => {
                let y = app(member("yield_", *sp), e.clone());
                if rest.is_empty() {
                    y
                } else {
                    let k = go(rest, member, span);
                    let d = app(member("delay", *sp), Expr { kind: ExprKind::Lambda(vec![Pat { kind: PatKind::Wild, span: *sp }], Box::new(k)), span: *sp });
                    app(app(member("combine", *sp), y), d)
                }
            }
            CeStmt::YieldBang(e, _) => e.clone(),
            CeStmt::Let(l) => {
                let k = go(rest, member, span);
                Expr { kind: ExprKind::Block(vec![Stmt::Let(l.clone()), Stmt::Expr(k.clone())]), span: l.span.to(k.span) }
            }
            CeStmt::For(p, src, body, sp) => {
                let b = go(body, member, span);
                let lam = Expr { kind: ExprKind::Lambda(vec![p.clone()], Box::new(b)), span: *sp };
                let f = app(app(member("for_", *sp), src.clone()), lam);
                if rest.is_empty() {
                    f
                } else {
                    let k = go(rest, member, span);
                    let d = app(member("delay", *sp), Expr { kind: ExprKind::Lambda(vec![Pat { kind: PatKind::Wild, span: *sp }], Box::new(k)), span: *sp });
                    app(app(member("combine", *sp), f), d)
                }
            }
            CeStmt::Assign(n, nsp, v) => {
                let k = go(rest, member, span);
                Expr { kind: ExprKind::Block(vec![Stmt::Assign(n.clone(), *nsp, v.clone()), Stmt::Expr(k.clone())]), span }
            }
        }
    }
    go(items, &member, span)
}

