                        ListPatElem::Star(..) => star = true,
                        ListPatElem::Pat(x) => {
                            let sp = self.simplify(x, &et);
                            if star {
                                suf.push(sp);
                            } else {
                                pre.push(sp);
                            }
                        }
                    }
                }
                P::List(pre, if star { Some(suf) } else { None })
            }
