            Ty::Con(n, args) if n == "bool" => {
                let _ = args;
                Some(vec![(Ctor::Bool(true), vec![]), (Ctor::Bool(false), vec![])])
            }
            Ty::Con(n, _) if n == "unit" => Some(vec![(Ctor::Unit, vec![])]),
