                        Some(out)
                    }
                    TypeDef::Record(fs) => {
                        let mut inst = Inst::default();
                        for (i, a) in args.iter().enumerate() {
                            inst.t.insert(i, a.clone());
                        }
                        let fts: Vec<Ty> = fs.iter().map(|(_, ft)| self.st.inst_ty(ft, &mut inst)).collect();
