        if let Some(c) = self.ctors.get(cname) {
            if c.type_name == tname {
                return Some(c.clone());
            }
        }
        self.ctors.values().find(|c| c.type_name == tname && c.name == cname).cloned()
    }

    fn useful(&mut self, rows: &[Vec<P>], tys: &[Ty]) -> Option<Vec<W>> {
        // expand or-patterns in the first column
        let mut expanded: Vec<Vec<P>> = Vec::new();
        for r in rows {
            expand_or(r, &mut expanded);
        }
        let rows = expanded;
        if tys.is_empty() {
            return if rows.is_empty() { Some(vec![]) } else { None };
        }
        let t = self.st.resolve(&tys[0]);
        let col: Vec<&P> = rows.iter().map(|r| &r[0]).collect();
        let present: Vec<Ctor> = present_ctors(&col);
        let all = self.all_ctors(&t, &col);
        if let Some(all) = &all {
            let complete = all.iter().all(|(c, _)| present.iter().any(|p| covers(p, c)) || col.iter().any(|p| list_star_covers(p, c)));
            if complete && !all.is_empty() {
                for (c, ats) in all {
                    let spec = specialize(&rows, c);
                    let mut ntys = ats.clone();
                    ntys.extend_from_slice(&tys[1..]);
                    if let Some(w) = self.useful(&spec, &ntys) {
                        let n = ats.len();
                        let head = W::C(c.clone(), w[..n].to_vec());
                        let mut out = vec![head];
                        out.extend_from_slice(&w[n..]);
                        return Some(out);
                    }
                }
                return None;
            }
        }
        // default matrix
        let def: Vec<Vec<P>> = rows.iter().filter(|r| matches!(r[0], P::Wild)).map(|r| r[1..].to_vec()).collect();
        let w = self.useful(&def, &tys[1..])?;
        let head = if present.is_empty() && !col.iter().any(|p| matches!(p, P::List(..))) {
            W::Wild
        } else {
            match &all {
                Some(all) => {
                    let missing = all.iter().find(|(c, _)| !present.iter().any(|p| covers(p, c)) && !col.iter().any(|p| list_star_covers(p, c)));
                    match missing {
                        Some((c, ats)) => W::C(c.clone(), vec![W::Wild; ats.len()]),
                        None => W::Wild,
                    }
                }
                None => W::Wild,
            }
        };
        let mut out = vec![head];
        out.extend(w);
        Some(out)
    }
}

fn display_ctor(c: &CtorInfo) -> String {
    c.name.clone()
}

fn expand_or(r: &[P], out: &mut Vec<Vec<P>>) {
    if r.is_empty() {
        out.push(vec![]);
        return;
    }
    match &r[0] {
        P::Or(alts) => {
            for a in alts {
                let mut nr = vec![a.clone()];
                nr.extend_from_slice(&r[1..]);
                expand_or(&nr, out);
            }
        }
        _ => out.push(r.to_vec()),
    }
}

fn collect_list_lens(p: &P, maxfixed: &mut i64, maxpre: &mut usize, maxsuf: &mut usize) {
    match p {
        P::List(pre, None) => *maxfixed = (*maxfixed).max(pre.len() as i64),
        P::List(pre, Some(suf)) => {
            *maxpre = (*maxpre).max(pre.len());
            *maxsuf = (*maxsuf).max(suf.len());
        }
        P::Or(alts) => {
            for a in alts {
                collect_list_lens(a, maxfixed, maxpre, maxsuf);
            }
        }
        _ => {}
    }
}

fn present_ctors(col: &[&P]) -> Vec<Ctor> {
    let mut out = Vec::new();
    for p in col {
        match p {
            P::C(c, _) => {
                if !out.contains(c) {
                    out.push(c.clone());
                }
            }
            P::List(pre, None) => {
                let c = Ctor::Len(pre.len());
                if !out.contains(&c) {
                    out.push(c);
                }
            }
            _ => {}
        }
    }
    out
}

fn covers(p: &Ctor, c: &Ctor) -> bool {
    match (p, c) {
        (Ctor::Adt { name: a, tname: ta, .. }, Ctor::Adt { name: b, tname: tb, .. }) => a == b && ta == tb,
        (Ctor::Record { .. }, Ctor::Record { .. }) => true,
        (Ctor::Tuple(_), Ctor::Tuple(_)) => true,
        _ => p == c,
    }
}

/// A star list pattern covers every length it can absorb.
fn list_star_covers(p: &P, c: &Ctor) -> bool {
    match (p, c) {
        (P::List(pre, Some(suf)), Ctor::Len(k)) => pre.len() + suf.len() <= *k,
        (P::List(pre, Some(suf)), Ctor::VarLen(a, b)) => pre.len() + suf.len() <= a + b,
        _ => false,
    }
}

fn specialize(rows: &[Vec<P>], c: &Ctor) -> Vec<Vec<P>> {
    let arity = match c {
        Ctor::Adt { arity, .. } => *arity,
        Ctor::Tuple(n) => *n,
        Ctor::Record { fields, .. } => fields.len(),
        Ctor::Len(k) => *k,
        Ctor::VarLen(a, b) => a + b,
        _ => 0,
    };
    let mut out = Vec::new();
    for r in rows {
        let head = &r[0];
        let rest = &r[1..];
        let sub: Option<Vec<P>> = match head {
            P::Wild => Some(vec![P::Wild; arity]),
            P::C(pc, args) => {
                if covers(pc, c) {
                    Some(args.clone())
                } else {
                    None
                }
            }
            P::List(pre, None) => match c {
                Ctor::Len(k) if pre.len() == *k => Some(pre.clone()),
                _ => None,
            },
            P::List(pre, Some(suf)) => match c {
                Ctor::Len(k) if pre.len() + suf.len() <= *k => {
                    let mut v = pre.clone();
                    v.extend(std::iter::repeat(P::Wild).take(k - pre.len() - suf.len()));
                    v.extend(suf.iter().cloned());
                    Some(v)
                }
                Ctor::VarLen(a, b) if pre.len() + suf.len() <= a + b => {
                    let mut v = pre.clone();
                    v.extend(std::iter::repeat(P::Wild).take(a - pre.len().min(*a)));
                    v.extend(std::iter::repeat(P::Wild).take(b - suf.len().min(*b)));
                    v.extend(suf.iter().cloned());
                    Some(v)
                }
                _ => None,
            },
            P::Or(_) => None,
        };
        if let Some(mut s) = sub {
            s.extend_from_slice(rest);
            out.push(s);
        }
    }
    out
}

pub fn show_witness(w: &W, nested: bool) -> String {
    match w {
        W::Wild => "_".into(),
        W::C(c, args) => match c {
            Ctor::Adt { name, .. } => {
                if args.is_empty() {
                    name.clone()
                } else {
                    let a: Vec<String> = args.iter().map(|x| show_witness(x, true)).collect();
                    let s = format!("{} {}", name, a.join(" "));
                    if nested {
                        format!("({})", s)
                    } else {
                        s
                    }
                }
            }
            Ctor::Tuple(_) => {
                let a: Vec<String> = args.iter().map(|x| show_witness(x, false)).collect();
                format!("({})", a.join(", "))
            }
            Ctor::Record { name, fields } => {
                let a: Vec<String> = fields.iter().zip(args.iter()).map(|(f, x)| format!("{} = {}", f, show_witness(x, false))).collect();
                format!("{} {{ {} }}", name, a.join(", "))
            }
            Ctor::Bool(b) => b.to_string(),
            Ctor::Unit => "()".into(),
            Ctor::Int(n) => n.to_string(),
            Ctor::Str(s) => format!("{:?}", s),
            Ctor::Len(_) => {
                let a: Vec<String> = args.iter().map(|x| show_witness(x, false)).collect();
                format!("[{}]", a.join(", "))
            }
            Ctor::VarLen(_, _) => {
                let mut a: Vec<String> = args.iter().map(|x| show_witness(x, false)).collect();
                a.push("*_".into());
                format!("[{}]", a.join(", "))
            }
        },
    }
}
