        scan_case_arities(f, names, out);
        return;
    }
    match &e.kind {
        ExprKind::If(c, a, b) => {
            scan_case_arities(c, names, out);
            scan_case_arities(a, names, out);
            scan_case_arities(b, names, out);
        }
        ExprKind::Match(s, arms) => {
            scan_case_arities(s, names, out);
            for a in arms {
                scan_case_arities(&a.body, names, out);
            }
        }
        ExprKind::Block(stmts) => {
            for s in stmts {
                match s {
                    Stmt::Let(l) => scan_case_arities(&l.value, names, out),
                    Stmt::Expr(x) | Stmt::Assign(_, _, x) => scan_case_arities(x, names, out),
                }
            }
        }
        ExprKind::Binary(_, a, b) => {
            scan_case_arities(a, names, out);
            scan_case_arities(b, names, out);
        }
        ExprKind::Tuple(xs) | ExprKind::List(xs) => {
            for x in xs {
                scan_case_arities(x, names, out);
            }
