// Lowering: pattern matching.

use crate::ast::*;
use crate::infer::*;
use crate::lower::*;
use crate::py::*;
use crate::source::Span;
use crate::types::*;
use std::collections::HashMap;

fn payload_simple(p: &Pat) -> bool {
    match &p.kind {
        PatKind::Var(_) | PatKind::Wild => true,
        PatKind::Tuple(ps) => ps.iter().all(|x| matches!(x.kind, PatKind::Var(_) | PatKind::Wild)),
        _ => false,
    }
}

pub fn irrefutable(p: &Pat) -> bool {
    match &p.kind {
        PatKind::Wild | PatKind::Var(_) => true,
        PatKind::Tuple(ps) => ps.iter().all(irrefutable),
        PatKind::Record(_, _, fs) => fs.iter().all(|(_, _, sp)| sp.as_ref().map_or(true, irrefutable)),
        PatKind::As(x, _, _) => irrefutable(x),
        _ => false,
    }
}

impl<'a> Lowerer<'a> {
    fn ladder_ok(&self, ty: &Option<Ty>, arms: &[Arm]) -> bool {
        let Some(Ty::Con(tn, _)) = ty else { return false };
        if tn != "Option" && tn != "Result" {
            return false;
        }
        arms.iter().all(|a| match &a.pat.kind {
            PatKind::Wild | PatKind::Var(_) => true,
            PatKind::Ctor(path, n, args) => {
                path.is_empty() && matches!(n.as_str(), "Some" | "None" | "Ok" | "Error") && args.iter().all(payload_simple)
            }
            _ => false,
        })
    }

    fn active_tag(&self, arms: &[Arm]) -> Option<String> {
        for a in arms {
            if let PatKind::Ctor(p, n, _) = &a.pat.kind {
                if p.is_empty() && self.ck.lookup_ctor(p, n).is_none() {
                    if let Some(t) = self.ck.active_cases.get(n) {
                        return Some(t.clone());
                    }
                }
            }
        }
        None
    }

    pub fn match_stmt(&mut self, s: &Expr, arms: &[Arm], span: Span, dest: &Dest) -> Vec<PS> {
        let ty = self.ty_of(s.span);
        if let Some(tag) = self.active_tag(arms) {
            return self.active_match(s, arms, &tag, dest);
        }
        if self.ladder_ok(&ty, arms) && !self.native_off() {
            return self.ladder(s, arms, &ty, dest);
        }
        if self.native {
            if let Some(Ty::Con(tn, _)) = &ty {
                if self.ck.types.get(tn).map_or(false, |t| matches!(t.def, TypeDef::Adt(_))) && tn != "Option" && tn != "Result" {
                    // --native lowers matches on your own types to isinstance ladders
                }
            }
        }
        let _ = span;
        let saved = std::mem::take(&mut self.pre);
        let subj = self.expr(s);
        let mut out = std::mem::replace(&mut self.pre, saved);
        let mut cases = Vec::new();
        for a in arms {
            self.scopes.push(HashMap::new());
            let pt = self.pat_ty(a.pat.span);
            let pat = self.py_pat(&a.pat, pt.as_ref());
            let guard = a.guard.as_ref().map(|g| {
                let saved = std::mem::take(&mut self.pre);
                let v = self.expr(g);
                self.pre = saved;
                v
            });
            let body = self.dest_stmts(&a.body, dest);
            self.scopes.pop();
            cases.push(Case { pat, guard, body });
        }
        let last_irrefutable = arms.last().map_or(false, |a| a.guard.is_none() && irrefutable(&a.pat));
        if !last_irrefutable {
            cases.push(Case {
                pat: PPat::Wild,
                guard: None,
                body: vec![PS::Raise(call_n("RuntimeError", vec![PE::Str("non-exhaustive match".into())]))],
            });
        }
        out.push(PS::Match(subj, cases));
        out
    }

    fn native_off(&self) -> bool {
        false
    }

    fn ladder(&mut self, s: &Expr, arms: &[Arm], _ty: &Option<Ty>, dest: &Dest) -> Vec<PS> {
        let mut out = Vec::new();
        // Map.tryFind k m: test membership instead of building an Option
        let mut tryfind: Option<(PE, PE)> = None;
        if let ExprKind::App(..) = &s.kind {
            let (f, args) = Self::spine(s);
            if let ExprKind::Qual(p, n, _) = &f.kind {
                if p.len() == 1 && p[0] == "Map" && n == "tryFind" && args.len() == 2 {
                    let saved = std::mem::take(&mut self.pre);
                    let k = self.expr(args[0]);
                    let m = self.expr(args[1]);
                    out.extend(std::mem::replace(&mut self.pre, saved));
                    tryfind = Some((k, m));
                }
            }
        }
        let subj: PE = if tryfind.is_some() {
            PE::NoneV
        } else {
            match &s.kind {
                ExprKind::Var(n) if self.lookup(n).is_some() => {
                    let saved = std::mem::take(&mut self.pre);
                    let v = self.expr(s);
                    out.extend(std::mem::replace(&mut self.pre, saved));
                    v
                }
                _ => {
                    let saved = std::mem::take(&mut self.pre);
                    let v = self.expr(s);
                    out.extend(std::mem::replace(&mut self.pre, saved));
                    let t = self.new_tmp();
                    out.push(PS::Assign(name(&t), v));
                    name(&t)
                }
            }
        };
        let has_guard = arms.iter().any(|a| a.guard.is_some());
        if has_guard {
            // fall-through form
            for a in arms {
                self.scopes.push(HashMap::new());
                let (cond, binds) = self.ladder_arm(&a.pat, &subj, &tryfind);
                let mut body = binds;
                let inner = self.dest_stmts(&a.body, dest);
                match &a.guard {
                    Some(g) => {
                        let saved = std::mem::take(&mut self.pre);
                        let gv = self.expr(g);
                        body.extend(std::mem::replace(&mut self.pre, saved));
                        body.push(PS::If(vec![(gv, inner)], None));
                    }
                    None => body.extend(inner),
                }
                self.scopes.pop();
                match cond {
                    Some(c) => out.push(PS::If(vec![(c, body)], None)),
                    None => out.extend(body),
                }
            }
            return out;
        }
        let mut ifarms = Vec::new();
        let mut els = None;
        let n = arms.len();
        for (i, a) in arms.iter().enumerate() {
            self.scopes.push(HashMap::new());
            let (cond, binds) = self.ladder_arm(&a.pat, &subj, &tryfind);
            let mut body = binds;
            body.extend(self.dest_stmts(&a.body, dest));
            self.scopes.pop();
            if i == n - 1 || cond.is_none() {
                els = Some(body);
                break;
            }
            ifarms.push((cond.unwrap(), body));
        }
        if ifarms.is_empty() {
            out.extend(els.unwrap_or_default());
        } else {
            out.push(PS::If(ifarms, els));
        }
        out
    }

    /// Condition and bindings for one ladder arm.
    fn ladder_arm(&mut self, p: &Pat, subj: &PE, tryfind: &Option<(PE, PE)>) -> (Option<PE>, Vec<PS>) {
        match &p.kind {
            PatKind::Wild => (None, vec![]),
            PatKind::Var(n) => {
                let py = self.bind(n, BKind::Value, false);
                (None, vec![PS::Assign(name(&py), subj.clone())])
            }
            PatKind::Ctor(_, c, args) => {
                let cls = ctor_py(c);
                self.note_ctor_type(if matches!(c.as_str(), "Some" | "None") { "Option" } else { "Result" });
                let payload = || -> PE { attr(subj.clone(), "_0") };
                let cond = match tryfind {
                    Some((k, m)) => {
                        let inn = PE::Cmp(Box::new(k.clone()), vec![(Cop::In, m.clone())]);
                        if c == "None" {
                            PE::Not(Box::new(inn))
                        } else {
                            inn
                        }
                    }
                    None => call_n("isinstance", vec![subj.clone(), name(&cls)]),
                };
                let mut binds = Vec::new();
                if let Some(a) = args.first() {
                    let val = match tryfind {
                        Some((k, m)) => PE::Index(Box::new(m.clone()), Box::new(k.clone())),
                        None => payload(),
                    };
                    match &a.kind {
                        PatKind::Var(n) => {
                            let py = self.bind(n, BKind::Value, false);
                            binds.push(PS::Assign(name(&py), val));
                        }
                        PatKind::Tuple(_) => {
                            let t = self.tuple_target(a);
                            binds.push(PS::Assign(t, val));
                        }
                        _ => {}
                    }
                }
                (Some(cond), binds)
            }
            _ => (None, vec![]),
        }
    }

    fn active_match(&mut self, s: &Expr, arms: &[Arm], tag: &str, dest: &Dest) -> Vec<PS> {
        let (names, partial) = self.ck.active_patterns.get(tag).cloned().unwrap_or_default();
        let saved = std::mem::take(&mut self.pre);
        let sv = self.expr(s);
        let mut out = std::mem::replace(&mut self.pre, saved);
        let recog = ap_name(&names);
        let t = self.new_tmp();
        out.push(PS::Assign(name(&t), call_n(&recog, vec![sv])));
        let is_bool = partial && {
            // predicate form: the recognizer returns bool
            let rt = self.ck.globals.get(tag).map(|l| l.scheme.ty.clone());
            matches!(rt, Some(Ty::Fun(_, _, ref r)) if matches!(**r, Ty::Con(ref n, _) if n == "bool"))
        };
        let mut ifarms = Vec::new();
        let mut els = None;
        let n = arms.len();
        for (i, a) in arms.iter().enumerate() {
            self.scopes.push(HashMap::new());
            let mut binds = Vec::new();
            let cond = match &a.pat.kind {
                PatKind::Ctor(_, c, args) => {
                    if partial {
                        if is_bool {
                            Some(name(&t))
                        } else {
                            self.needs.option = true;
                            if let Some(arg) = args.first() {
                                if let PatKind::Var(v) = &arg.kind {
