                        let gv = self.expr(g);
                        body.extend(std::mem::replace(&mut self.pre, saved));
                        body.push(PS::If(vec![(gv, inner)], None));
                    }
                    None => body.extend(inner),
                }
                self.scopes.pop();
                match cond {
                    Some(c) => out.push(PS::If(vec![(c, body)], None)),
                    None => out.extend(body),
                }
            }
            return out;
        }
        let mut ifarms = Vec::new();
        let mut els = None;
        let n = arms.len();
        for (i, a) in arms.iter().enumerate() {
            self.scopes.push(HashMap::new());
            let (cond, binds) = self.ladder_arm(&a.pat, &subj, &tryfind);
            let mut body = binds;
            body.extend(self.dest_stmts(&a.body, dest));
            self.scopes.pop();
            if i == n - 1 || cond.is_none() {
                els = Some(body);
                break;
            }
            ifarms.push((cond.unwrap(), body));
        }
        if ifarms.is_empty() {
            out.extend(els.unwrap_or_default());
        } else {
            out.push(PS::If(ifarms, els));
        }
        out
    }

    /// Condition and bindings for one ladder arm.
    fn ladder_arm(&mut self, p: &Pat, subj: &PE, tryfind: &Option<(PE, PE)>) -> (Option<PE>, Vec<PS>) {
        match &p.kind {
            PatKind::Wild => (None, vec![]),
            PatKind::Var(n) => {
                let py = self.bind(n, BKind::Value, false);
                (None, vec![PS::Assign(name(&py), subj.clone())])
            }
            PatKind::Ctor(_, c, args) => {
                let cls = ctor_py(c);
                self.note_ctor_type(if matches!(c.as_str(), "Some" | "None") { "Option" } else { "Result" });
                let payload = || -> PE { attr(subj.clone(), "_0") };
                let cond = match tryfind {
                    Some((k, m)) => {
                        let inn = PE::Cmp(Box::new(k.clone()), vec![(Cop::In, m.clone())]);
                        if c == "None" {
                            PE::Not(Box::new(inn))
                        } else {
                            inn
                        }
                    }
                    None => call_n("isinstance", vec![subj.clone(), name(&cls)]),
                };
                let mut binds = Vec::new();
                if let Some(a) = args.first() {
                    let val = match tryfind {
                        Some((k, m)) => PE::Index(Box::new(m.clone()), Box::new(k.clone())),
                        None => payload(),
                    };
                    match &a.kind {
                        PatKind::Var(n) => {
                            let py = self.bind(n, BKind::Value, false);
                            binds.push(PS::Assign(name(&py), val));
                        }
                        PatKind::Tuple(_) => {
                            let t = self.tuple_target(a);
                            binds.push(PS::Assign(t, val));
                        }
                        _ => {}
                    }
                }
                (Some(cond), binds)
            }
            _ => (None, vec![]),
        }
    }

    fn active_match(&mut self, s: &Expr, arms: &[Arm], tag: &str, dest: &Dest) -> Vec<PS> {
        let (names, partial) = self.ck.active_patterns.get(tag).cloned().unwrap_or_default();
        let saved = std::mem::take(&mut self.pre);
        let sv = self.expr(s);
        let mut out = std::mem::replace(&mut self.pre, saved);
        let recog = ap_name(&names);
        let t = self.new_tmp();
        out.push(PS::Assign(name(&t), call_n(&recog, vec![sv])));
        let is_bool = partial && {
            // predicate form: the recognizer returns bool
            let rt = self.ck.globals.get(tag).map(|l| l.scheme.ty.clone());
            matches!(rt, Some(Ty::Fun(_, _, ref r)) if matches!(**r, Ty::Con(ref n, _) if n == "bool"))
        };
        let mut ifarms = Vec::new();
        let mut els = None;
        let n = arms.len();
        for (i, a) in arms.iter().enumerate() {
            self.scopes.push(HashMap::new());
            let mut binds = Vec::new();
            let cond = match &a.pat.kind {
                PatKind::Ctor(_, c, args) => {
                    if partial {
                        if is_bool {
                            Some(name(&t))
                        } else {
                            self.needs.option = true;
                            if let Some(arg) = args.first() {
                                if let PatKind::Var(v) = &arg.kind {
                                    let py = self.bind(v, BKind::Value, false);
                                    binds.push(PS::Assign(name(&py), attr(name(&t), "_0")));
                                }
                            }
                            Some(call_n("isinstance", vec![name(&t), name("Some")]))
                        }
                    } else {
                        for (j, arg) in args.iter().enumerate() {
                            if let PatKind::Var(v) = &arg.kind {
                                let py = self.bind(v, BKind::Value, false);
                                binds.push(PS::Assign(name(&py), attr(name(&t), &format!("_{}", j))));
                            }
                        }
                        Some(call_n("isinstance", vec![name(&t), name(&format!("_{}", c))]))
                    }
                }
                PatKind::Var(v) => {
                    let py = self.bind(v, BKind::Value, false);
                    binds.push(PS::Assign(name(&py), name(&t)));
                    None
                }
                _ => None,
            };
            let mut body = binds;
            body.extend(self.dest_stmts(&a.body, dest));
            self.scopes.pop();
            match cond {
                Some(c) if !(partial && i == n - 1) => ifarms.push((c, body)),
                Some(c) => ifarms.push((c, body)),
                None => {
                    els = Some(body);
                    break;
                }
            }
        }
        if els.is_none() {
            els = Some(vec![PS::Raise(call_n("RuntimeError", vec![PE::Str("non-exhaustive match".into())]))]);
        }
        out.push(PS::If(ifarms, els));
        out
    }

    // ---- python patterns ----------------------------------------------------

    pub fn py_pat(&mut self, p: &Pat, t: Option<&Ty>) -> PPat {
        match &p.kind {
            PatKind::Wild => PPat::Wild,
            PatKind::Var(n) => PPat::Capture(self.bind(n, BKind::Value, false)),
            PatKind::Int(n) => PPat::Value(PE::Int(*n)),
            PatKind::Str(s) => PPat::Value(PE::Str(s.clone())),
            PatKind::Bool(b) => PPat::Value(PE::Bool(*b)),
            PatKind::Unit => PPat::Value(PE::NoneV),
            PatKind::Tuple(ps) => {
                let ts: Vec<Option<Ty>> = match t {
                    Some(Ty::Tuple(ts)) => ts.iter().cloned().map(Some).collect(),
                    _ => vec![None; ps.len()],
                };
                PPat::Tuple(ps.iter().zip(ts.iter()).map(|(x, xt)| self.py_pat(x, xt.as_ref())).collect())
            }
            PatKind::List(es) => {
                let et = match t {
                    Some(Ty::Con(_, a)) if !a.is_empty() => Some(a[0].clone()),
                    _ => None,
                };
                let v = es
                    .iter()
                    .map(|e| match e {
                        ListPatElem::Pat(x) => self.py_pat(x, et.as_ref()),
                        ListPatElem::Star(Some(n), _) => PPat::Star(Some(self.bind(n, BKind::Value, false))),
                        ListPatElem::Star(None, _) => PPat::Star(None),
                    })
                    .collect();
                PPat::Seq(v)
            }
            PatKind::Ctor(path, n, args) => {
                let c = self.ck.lookup_ctor(path, n);
                let Some(c) = c else { return PPat::Wild };
                self.note_ctor_type(&c.type_name);
                if let Some(TypeInfo { def: TypeDef::Opaque(_), .. }) = self.ck.types.get(&c.type_name) {
                    return self.py_pat(&args[0], None);
                }
                let prefix = match self.project_modules.get(&path.join(".")) {
                    Some(py) if !path.is_empty() => format!("{}.", py),
                    _ => match &c.module {
                        Some(m) if path.is_empty() => self.project_modules.get(m).map(|py| format!("{}.", py)).unwrap_or_default(),
                        _ => String::new(),
                    },
                };
                let ats: Vec<Option<Ty>> = match t {
                    Some(Ty::Con(_, targs)) => c.args.iter().map(|a| Some(crate::lower2::subst_gen(a, targs))).collect(),
                    _ => vec![None; args.len()],
                };
                let sub = args.iter().zip(ats.iter()).map(|(a, at)| self.py_pat(a, at.as_ref())).collect();
                PPat::Class(format!("{}{}", prefix, ctor_py(n)), sub, vec![])
            }
            PatKind::Record(path, n, fields) => {
                let key = if path.is_empty() { n.clone() } else { format!("{}.{}", path.join("."), n) };
                let fts: Vec<(String, Ty)> = match self.ck.types.get(&key) {
                    Some(TypeInfo { def: TypeDef::Record(fs), .. }) => fs.clone(),
                    _ => vec![],
                };
                let mut kws = Vec::new();
                for (f, _, sub) in fields {
                    let ft = fts.iter().find(|(x, _)| x == f).map(|(_, t)| t.clone());
                    let sp = match sub {
                        Some(x) => self.py_pat(x, ft.as_ref()),
                        None => PPat::Capture(self.bind(f, BKind::Value, false)),
                    };
                    kws.push((mangle(f), sp));
                }
                let prefix = match self.project_modules.get(&path.join(".")) {
                    Some(py) if !path.is_empty() => format!("{}.", py),
                    _ => String::new(),
                };
                PPat::Class(format!("{}{}", prefix, n), vec![], kws)
            }
            PatKind::Or(alts) => PPat::Or(alts.iter().map(|a| self.py_pat(a, t)).collect()),
            PatKind::As(x, n, _) => {
                let inner = self.py_pat(x, t);
                PPat::As(Box::new(inner), self.bind(n, BKind::Value, false))
            }
        }
    }
}

pub fn ap_name(cases: &[String]) -> String {
    format!("_ap_{}", cases.join("_"))
}

