        for n in names {
            let h = HELPERS.iter().find(|x| x.name == n).unwrap();
            s.push_str(h.text);
            s.push('\n');
        }
        s.push_str(&body);
        if s.is_empty() {
            s.push_str("pass\n");
        }
        s
    }
