    /// A saturated self call in tail position: rebind the parameters and loop.
    pub fn tail_call(&mut self, e: &Expr) -> Option<Vec<PS>> {
        let (sn, params) = self.fn_stack.last()?.tce.clone()?;
        let (f, args) = tail_spine(e)?;
