        let parsed = match crate::parser::parse_program(input) {
            Ok(p) => p,
            Err(d) => return Err(EvalErr::Parse(render(input, &d))),
        };
        let k = parsed.decls.len();
        let src = session_source(&self.entries, input);
        let prog = match crate::parser::parse_program(&src) {
            Ok(p) => p,
            Err(d) => return Err(EvalErr::Parse(render(&src, &d))),
        };
        let n = prog.decls.len();
        let first = n - k;
        // the kind of input
        let trailing_expr = matches!(prog.decls.last(), Some(Decl::Expr(_)));
        let expr_only = k == 1 && trailing_expr && (self.mode == Mode::Kernel || !block);
        let (defs_end, trailing) = match self.mode {
            Mode::Repl => {
                if expr_only {
                    (first, true)
                } else {
                    (n, false)
                }
            }
            Mode::Kernel => {
                if trailing_expr {
                    (n - 1, true)
                } else {
                    (n, false)
                }
            }
        };
