                            }
                        }
                    }
                }
            }
        }
        // holes block compilation
        let input_lo = src.len() - input.len();
        let holes: Vec<Diag> = c
            .holes
            .iter()
            .filter(|h| h.span.lo >= input_lo)
            .map(|h| {
                let t = c.st.show(&h.ty);
                let name = match &h.name {
                    Some(n) => format!("?{}", n),
                    None => "?".to_string(),
                };
                let sugg = crate::holes::suggest_text(&c, h);
                Diag::error(format!("cannot compile: unfilled hole `{}` has type `{}`{} (fill it in)", name, t, sugg), h.span)
            })
            .collect();
        if !holes.is_empty() {
            let errs = holes.iter().map(|d| render(&src, d)).collect();
            return Err(EvalErr::Compile(echoes, errs));
        }
        // texts of the definitions already in the session
        let prev_texts: HashSet<&str> = prog.decls[..first].iter().map(|d| decl_text(&src, d)).collect();
        let mut l = Lowerer::new(&c);
        l.collect_ordering();
        l.bind_externs(&prog.decls);
        for d in &prog.decls[..first] {
            let _ = l.lower_decl(d, None);
        }
        l.needs = Default::default();
        l.collect_ordering();
        let mut code: Vec<PS> = Vec::new();
        let mut type_decls: Vec<Decl> = Vec::new();
        for (i, d) in prog.decls.iter().enumerate().skip(first) {
            let dup = i < defs_end && prev_texts.contains(decl_text(&src, d));
            if i >= defs_end {
                // the trailing expression: printed unless it is unit
