                    let t = l.ty_of(e.span);
                    if t.as_ref().map_or(false, is_unit) {
                        code.extend(l.lower_decl(d, None));
                    } else {
                        let saved = std::mem::take(&mut l.pre);
                        let v = match &e.kind {
                            ExprKind::Match(s, arms) => {
                                let tmp = l.new_tmp();
                                let st = l.match_stmt(s, arms, e.span, &Dest::Assign(tmp.clone()));
                                l.pre.extend(st);
                                name(&tmp)
                            }
                            _ => l.expr(e),
                        };
                        let mut out = std::mem::replace(&mut l.pre, saved);
                        out.push(PS::Expr(call_n("print", vec![v])));
                        code.extend(out);
                    }
                }
                continue;
            }
            let stmts = l.lower_decl(d, None);
            if !dup {
                code.extend(stmts);
                if matches!(d, Decl::Type(_)) {
                    type_decls.push(d.clone());
                }
            }
        }
        let printer = Printer { py311: false };
        let mut body = String::new();
        printer.stmts(&code, 0, &mut body);
        let types_text = l.type_classes(&type_decls);
        let parts = l.parts(types_text);
        let mut out = String::new();
        for ch in chunks(&parts.prelude) {
            if dedupable(&ch) {
                if self.sent.contains(&ch) {
                    continue;
                }
                self.sent.insert(ch.clone());
            }
            out.push_str(&ch);
        }
        out.push_str(&parts.types);
        out.push_str(&parts.codecs);
        out.push_str(&body);
        let all_dup = (first..defs_end).all(|i| prev_texts.contains(decl_text(&src, &prog.decls[i])));
        if out.is_empty() && !(defs_end > first && all_dup) && !(trailing && defs_end == first) {
            out.push_str("pass\n");
        }
        // remember the definitions
        let stored = defs_end > first;
        if stored {
            let entry = if block && self.mode == Mode::Repl { format!("{}\n", input.trim_end_matches('\n')) } else { input.to_string() };
            self.entries.push(entry);
        }
        Ok(EvalOk { echoes, code: out, stored })
    }

    /// `:type expr` / the kernel's `type` op.
    pub fn type_of(&mut self, expr: &str) -> Result<String, Vec<String>> {
        let src = session_source(&self.entries, expr);
        let lexed = crate::lexer::lex(&src);
        let mut diags: Vec<Diag> = Vec::new();
