                                if l.trim() == ":}" {
                                    break;
                                }
                                lines.push(l);
                            }
                        }
                    }
                    let text = lines.join("\n");
                    if !text.trim().is_empty() {
                        repl.eval(&text, true);
                    }
                    if eof {
                        // the block ended at end of input
                        prompt("pyfun> ");
                        println!();
                        break;
                    }
                }
                _ => println!("unknown command `{}` — :help for the list", word),
            }
            continue;
        }
        repl.eval(&line, false);
    }
    if let Some(w) = repl.worker.take() {
        w.kill();
    }
    std::process::exit(0);
}

