struct Cand {
    name: String,
    scheme: Scheme,
    user: bool,
    base: usize,
}

fn count_vars(t: &Ty, seen: &mut HashSet<String>) {
    match t {
        Ty::Gen(i) => {
            seen.insert(format!("t{}", i));
        }
        Ty::Var(v) => {
            seen.insert(format!("v{}", v));
        }
        Ty::Con(_, args) => {
            for a in args {
                count_vars(a, seen);
            }
        }
        Ty::Tuple(ts) => {
            for a in ts {
                count_vars(a, seen);
            }
        }
        Ty::Fun(a, e, r) => {
            count_vars(a, seen);
            if let Some(EffTail::Gen(i)) = e.tail {
                seen.insert(format!("e{}", i));
            }
            count_vars(r, seen);
        }
        Ty::Num(k, u) => {
            if let Kind::Gen(i) = k {
                seen.insert(format!("k{}", i));
            }
            for a in u.0.keys() {
                if let UAtom::Gen(i) = a {
                    seen.insert(format!("u{}", i));
                }
            }
        }
    }
}

