                                self.unify_at(&ft, bt, p.span)?;
                            }
                        }
                    }
                }
                binds.extend(first_binds.unwrap_or_default());
                Ok(())
            }
            PatKind::As(inner, n, _) => {
                self.check_pat_collect(inner, t, binds)?;
                binds.push((n.clone(), t.clone()));
                Ok(())
            }
