    fn infer_record(&mut self, path: &[String], name: &str, cspan: Span, fields: &[(String, Span, Expr)], span: Span) -> R<Ty> {
        let tkey = self.type_key(path, name);
        let Some((rt, fts)) = self.inst_record(&tkey) else {
            return Err(Diag::error(format!("`{}` is not a record type", name), span.to(cspan)));
        };
        let mut seen: Vec<&str> = Vec::new();
        for (f, fspan, v) in fields {
            if seen.contains(&f.as_str()) {
                return Err(Diag::error(format!("field `{}` is set twice", f), *fspan));
            }
            seen.push(f);
            let Some((_, ft)) = fts.iter().find(|(n, _)| n == f) else {
                return Err(Diag::error(format!("record `{}` has no field `{}`", name, f), *fspan));
            };
            let ft = ft.clone();
            let tv = self.infer(v)?;
            self.unify_at(&ft, &tv, v.span)?;
