let greet name = print name
let twice f x = f (f x)
type P = { x: int, y: int }
let p = P { x = 1, y = 2 }
let q = { p with x = 3 }
let r = p.x + q.y
let s = [1, 2] |> List.map (fun n -> n + 1)
let t = (1, "a")
let (a, b) = t
