// Recursive-descent parser with an offside rule driven by token columns.

use crate::ast::*;
use crate::diag::Diag;
use crate::lexer::{describe, FPiece, Tok, Token};
use crate::source::Span;

#[derive(Clone, Copy, Debug)]
enum Layout {
    /// statements of a block start at this column
    Block(usize),
    /// inside brackets: line breaks mean nothing
    NoLayout,
    /// one item of a computation expression body
    CeItem { item_col: usize, expr_col: usize, line: usize, kw: &'static str },
}

pub struct Parser {
    toks: Vec<Token>,
    pos: usize,
    layout: Vec<Layout>,
    docs: Vec<(usize, String)>,
    pub errors: Vec<Diag>,
    /// index of a token that starts a statement: never a layout boundary
    anchor: usize,
}

type PResult<T> = Result<T, Diag>;

fn is_continuation(t: &Tok) -> bool {
    matches!(
        t,
        Tok::Plus
            | Tok::Minus
            | Tok::Star
            | Tok::Slash
            | Tok::SlashSlash
            | Tok::Percent
            | Tok::StarStar
            | Tok::EqEq
            | Tok::NotEq
            | Tok::Lt
            | Tok::Le
            | Tok::Gt
            | Tok::Ge
            | Tok::PipeRight
            | Tok::PipeLeft
            | Tok::ComposeRight
            | Tok::ComposeLeft
            | Tok::And
            | Tok::Or
            | Tok::Dot
            | Tok::Eq
            | Tok::Arrow
            | Tok::Colon
            | Tok::Bar
            | Tok::Then
            | Tok::Elif
            | Tok::Else
            | Tok::With
            | Tok::RParen
            | Tok::RBracket
            | Tok::RBrace
            | Tok::Comma
    )
}

fn starts_atom(t: &Tok) -> bool {
    matches!(
        t,
        Tok::Int(_)
            | Tok::Float(_)
            | Tok::Str(_)
            | Tok::FStr(_)
            | Tok::Ident(_)
            | Tok::Upper(_)
            | Tok::Hole(_)
            | Tok::True
            | Tok::False
            | Tok::LParen
            | Tok::LBracket
            | Tok::LBrace
    )
}

#[derive(PartialEq)]
enum Boundary {
    No,
    Statement,
    Block,
}

impl Parser {
    pub fn new(toks: Vec<Token>, docs: Vec<(usize, String)>) -> Parser {
        Parser { toks, pos: 0, layout: vec![Layout::Block(1)], docs, errors: Vec::new(), anchor: usize::MAX }
    }

    // ---- token access -------------------------------------------------

    fn raw(&self) -> &Token {
        &self.toks[self.pos.min(self.toks.len() - 1)]
    }
    fn raw_at(&self, k: usize) -> &Token {
        &self.toks[(self.pos + k).min(self.toks.len() - 1)]
    }

    fn boundary_of(&self, t: &Token) -> Boundary {
        if t.tok == Tok::Eof {
            return Boundary::Statement;
        }
        if !t.bol || t.span.lo == self.anchor {
            return Boundary::No;
        }
        match self.layout.last() {
            None | Some(Layout::NoLayout) => Boundary::No,
            Some(Layout::Block(col)) => {
                if t.col < *col {
                    Boundary::Block
                } else if t.col == *col && !is_continuation(&t.tok) {
                    Boundary::Statement
                } else {
                    Boundary::No
                }
            }
            Some(Layout::CeItem { item_col, expr_col, .. }) => {
                if t.col > *expr_col || (is_continuation(&t.tok) && t.col > *item_col) {
                    Boundary::No
                } else {
                    Boundary::Statement
                }
            }
        }
    }

    fn at_boundary(&self) -> bool {
        self.boundary_of(self.raw()) != Boundary::No
    }

    /// The next token if it is not cut off by layout.
    fn peek(&self) -> Option<&Tok> {
        let t = self.raw();
        if self.boundary_of(t) != Boundary::No {
            None
        } else {
            Some(&t.tok)
        }
    }

    fn check(&self, t: &Tok) -> bool {
        self.peek() == Some(t)
    }

    fn bump(&mut self) -> Token {
        let t = self.raw().clone();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
    }

    fn eat(&mut self, t: &Tok) -> bool {
        if self.check(t) {
            self.bump();
            true
        } else {
            false
        }
    }

    fn describe_next(&self) -> String {
        let t = self.raw();
        if t.tok == Tok::Eof {
            return "end of input".into();
        }
        if matches!(self.layout.last(), Some(Layout::CeItem { .. })) {
            return describe(&t.tok);
        }
        match self.boundary_of(t) {
            Boundary::Block => "end of block".into(),
            Boundary::Statement => "end of statement".into(),
            Boundary::No => describe(&t.tok),
        }
    }

    fn next_span(&self) -> Span {
        self.raw().span
    }

    fn err_expected(&self, what: &str) -> Diag {
        Diag::error(format!("expected {}, found {}", what, self.describe_next()), self.err_span())
    }

    fn expect(&mut self, t: &Tok, what: &str) -> PResult<Token> {
        if self.check(t) {
            Ok(self.bump())
        } else {
            Err(self.err_expected(what))
        }
    }

    fn prev_end(&self) -> usize {
        if self.pos == 0 {
            0
        } else {
            self.toks[self.pos - 1].span.hi
        }
    }

    fn with_layout<T>(&mut self, l: Layout, f: impl FnOnce(&mut Parser) -> PResult<T>) -> PResult<T> {
        self.layout.push(l);
        let r = f(self);
        self.layout.pop();
        r
    }

    // ---- program ------------------------------------------------------

    pub fn program(&mut self) -> PResult<Program> {
        let mut decls = Vec::new();
        let mut last_line = 0usize;
        while self.raw().tok != Tok::Eof {
            let doc = self.take_doc(last_line, self.raw().line);
            let d = self.decl(doc)?;
            decls.push(d);
            last_line = self.toks[self.pos.saturating_sub(1)].line;
            let _ = last_line;
            last_line = self.line_before();
        }
        Ok(Program { decls })
    }

    fn line_before(&self) -> usize {
        if self.pos == 0 {
            0
        } else {
            // the line on which the previous token ends
            let t = &self.toks[self.pos - 1];
            t.line + 0
        }
    }

    fn take_doc(&mut self, after_line: usize, line: usize) -> Option<String> {
        let mut lines = Vec::new();
        for (l, text) in &self.docs {
            if *l > after_line && *l < line {
                lines.push(text.clone());
            }
        }
        if lines.is_empty() {
            None
        } else {
            Some(lines.join("\n"))
        }
    }

    fn decl(&mut self, doc: Option<String>) -> PResult<Decl> {
        let start = self.raw().span.lo;
        self.anchor = start;
        match self.raw().tok.clone() {
            Tok::Let => {
                let l = self.let_decl(doc)?;
                Ok(Decl::Let(l))
            }
            Tok::Type => self.type_decl(doc, false),
            Tok::Ident(ref s) if s == "opaque" && self.raw_at(1).tok == Tok::Type => {
                self.bump();
                self.type_decl(doc, true)
            }
            Tok::Measure => self.measure_decl(),
            Tok::Extern => self.extern_decl(doc),
            Tok::Import => {
                self.bump();
                match self.raw().tok.clone() {
                    Tok::Upper(n) => {
                        let t = self.bump();
                        Ok(Decl::Import(n, t.span))
                    }
                    _ => Err(self.err_expected("a module name")),
                }
            }
            Tok::Module => self.module_decl(),
            _ => {
                // expression statement (or assignment)
                if let (Tok::Ident(name), Tok::LArrow) = (self.raw().tok.clone(), self.raw_at(1).tok.clone()) {
                    let nt = self.bump();
                    self.bump();
                    let v = self.expr()?;
                    let _ = start;
                    return Ok(Decl::Assign(name, nt.span, v));
                }
                let e = self.expr()?;
                Ok(Decl::Expr(e))
            }
        }
    }

    fn module_decl(&mut self) -> PResult<Decl> {
        let kw = self.bump();
        let (name, nspan) = match self.raw().tok.clone() {
            Tok::Upper(n) => {
                let t = self.bump();
                (n, t.span)
            }
            _ => return Err(self.err_expected("a module name")),
        };
        self.expect(&Tok::Eq, "`=`")?;
        let first = self.raw().clone();
        if first.tok == Tok::Eof || !first.bol || self.boundary_of(&first) != Boundary::No {
            return Err(self.err_expected("an indented module body"));
        }
        let col = first.col;
        let mut decls = Vec::new();
        self.layout.push(Layout::Block(col));
        let r = (|| -> PResult<()> {
            loop {
                let doc_line = self.raw().line;
                let doc = self.take_doc(self.line_before(), doc_line);
                let d = self.decl(doc)?;
                decls.push(d);
                let t = self.raw();
                if t.tok == Tok::Eof || (t.bol && t.col < col) {
                    break;
                }
                if t.bol && t.col == col {
                    continue;
                }
                return Err(self.err_expected("end of the block"));
            }
            Ok(())
        })();

