fn upper_atom(&mut self) -> PResult<Expr> {
        let first = self.bump();
        let mut path = Vec::new();
        let mut name = match &first.tok {
            Tok::Upper(n) => n.clone(),
            _ => unreachable!(),
        };
        let mut last_span = first.span;
        // A.B.c / A.B
        while self.raw().tok == Tok::Dot && !self.at_boundary_tok(1) {
            match self.raw_at(1).tok.clone() {
                Tok::Upper(n) => {
                    self.bump();
                    let t = self.bump();
                    path.push(std::mem::replace(&mut name, n));
                    last_span = t.span;
                }
                Tok::Ident(n) => {
                    self.bump();
                    let t = self.bump();
                    path.push(name);
                    let span = first.span.to(t.span);
                    let _ = last_span;
                    return Ok(Expr { kind: ExprKind::Qual(path, n, t.span), span });
                }
                _ => break,
            }
        }
        let ctor_span = last_span;
        if self.check(&Tok::LBrace) {
            // record construction, or a user CE builder `Maybe { ... }`
            let next = self.raw_at(1).tok.clone();
            if let Tok::Ident(field) = &next {
                // `T { x = ...`: a record; `T { x y ...`: neither
                if path.is_empty() && !matches!(self.raw_at(2).tok, Tok::Eq | Tok::RBrace | Tok::Comma) {
                    let sp = self.raw_at(1).span;
                    return Err(Diag::error(
                        format!(
