mkdir -p /tmp/pf/msug && cat > /tmp/pf/msug/probe.py <<'EOF'
import random, subprocess, os, sys, json
random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 1)
mem = [l.strip() for l in open('/tmp/pf/members.txt') if l.strip()]
alpha = 'abcdefghijklmnopqrstuvwxyz'
def mutate(s, k):
    s = list(s)
    for _ in range(k):
        op = random.choice('sdi')
        if op == 's' and s:
            i = random.randrange(len(s)); s[i] = random.choice(alpha)
        elif op == 'd' and len(s) > 1:
            i = random.randrange(len(s)); del s[i]
        else:
            i = random.randrange(len(s)+1); s.insert(i, random.choice(alpha))
    return ''.join(s)
names = set(m.split('.')[1] for m in mem)
probes = []
for _ in range(int(sys.argv[2]) if len(sys.argv)>2 else 200):
    m = random.choice(mem); mod, n = m.split('.')
    k = random.choice([1,2,2,3,3,4,5])
    t = mutate(n, k)
    if t in names or not t or not t[0].islower(): continue
    probes.append((mod, t))
os.makedirs('/tmp/pf/msug/w', exist_ok=True)
src = ''.join(f'let x{i} = {mod}.{t}\n' for i,(mod,t) in enumerate(probes))
open('/tmp/pf/msug/w/a.pyfun','w').write(src)
out = subprocess.run(['/tmp/pf/orig/pyfun','check','a.pyfun'],cwd='/tmp/pf/msug/w',capture_output=True,text=True).stderr
res = {}
import re
for line in out.splitlines():
    mm = re.match(r"error: `(\w+)` is not a member of `(\w+)`(?: \(did you mean `\w+\.(\w+)`\?\))?", line)
    if mm: res[(mm.group(2), mm.group(1))] = mm.group(3)
with open('/tmp/pf/msug/data.jsonl','a') as f:
    for (mod,t) in probes:
        if (mod,t) in res:
            f.write(json.dumps([mod,t,res[(mod,t)]])+'\n')
print(len(probes), len(res))
EOF
