arguments.command:
cat > /tmp/pf/msug/an.py <<'EOF'
import json, collections
mem = [l.strip() for l in open('/tmp/pf/members.txt') if l.strip()]
bymod = collections.defaultdict(list)
for m in mem:
    a,b = m.split('.'); bymod[a].append(b)
data = [json.loads(l) for l in open('/tmp/pf/msug/data.jsonl')]
def lev(a,b):
    prev = list(range(len(b)+1))
    for i,ca in enumerate(a,1):
        cur=[i]
        for j,cb in enumerate(b,1):
            cur.append(min(prev[j]+1,cur[j-1]+1,prev[j-1]+(ca!=cb)))
        prev=cur
    return prev[-1]
def jaro(s1,s2):
    if not s1 and not s2: return 1.0
    if not s1 or not s2: return 0.0
    w = max(max(len(s1),len(s2))//2-1,0)
    m1=[False]*len(s1); m2=[False]*len(s2); m=0
    for i,c in enumerate(s1):
        for j in range(max(0,i-w), min(len(s2), i+w+1)):
            if not m2[j] and s2[j]==c:
                m1[i]=m2[j]=True; m+=1; break
    if m==0: return 0.0
    k=0; t=0
    for i in range(len(s1)):
        if m1[i]:
            while not m2[k]: k+=1
            if s1[i]!=s2[k]: t+=1
            k+=1
    t//=2
    return (m/len(s1)+m/len(s2)+(m-t)/m)/3
def jw(s1,s2):
    j=jaro(s1,s2); p=0
    for a,b in zip(s1,s2):
        if a==b and p<4: p+=1
        else: break
    return j+0.1*p*(1-j)
# check for each datum: which candidates; is suggestion the lev-best?
ok_lev=0; amb=0
rows=[]
for mod,t,s in data:
    cands = bymod[mod]
    ds = sorted((lev(t,c),c) for c in cands)
    best = ds[0]
    rows.append((mod,t,s,ds[:3], max((jw(t,c),c) for c in cands)))
import sys
mode = sys.argv[1] if len(sys.argv)>1 else 'lev'
if mode=='lev':
    # tabulate by (len(t), best lev distance): suggested or not
    tab = collections.defaultdict(lambda:[0,0])
    for mod,t,s,ds,j in rows:
        key=(len(t), ds[0][0])
        tab[key][1 if s else 0]+=1
    for k in sorted(tab): print(k, 'none=%d sugg=%d'%tuple(tab[k]))
elif mode=='jw':
    tab=[]
    for mod,t,s,ds,j in rows:
        tab.append((j[0], bool(s), mod, t, s, j[1]))
    tab.sort()
    for x in tab: print('%.4f %s %s.%s -> %s (jw best %s)'%x)
EOF
