            let mut reg = std::mem::take(&mut self.codecs);
            let r = self.codec_of(&inner, &mut reg);
            match r {
                Ok(c) => {
                    self.codecs = reg;
                    self.auto_codecs.insert(key(*span), c);
                }
                Err(msg) => {
                    self.codecs = reg;
                    self.errors.push(Diag::error(msg, *span));
                }
            }
        }
        self.auto_types = uses;
