pub fn fmt_unit(u: &UnitExpr) -> String {
    let f = |v: &Vec<(String, i64)>| -> String {
        v.iter()
            .map(|(n, e)| if *e == 1 { n.clone() } else { format!("{}^{}", n, e) })
            .collect::<Vec<_>>()
            .join(" ")
    };
    if u.num.is_empty() && u.den.is_empty() {
        return "1".into();
    }
    let num = if u.num.is_empty() { "1".to_string() } else { f(&u.num) };
    if u.den.is_empty() {
        num
    } else {
        format!("{}/{}", num, f(&u.den))
    }
}

