        // the bracket a bracketed layout belongs to (it was just read)
        let opener = (1..=2).filter_map(|k| self.pos.checked_sub(k)).map(|i| self.toks[i].tok.clone()).find(|t| matches!(t, Tok::LParen | Tok::LBracket | Tok::LBrace));
        let at = self.layout.len();
