python3 - <<'EOF'
p='/workspace/src/parser.rs'
s=open(p).read()
old='''    fn with_layout<T>(&mut self, l: Layout, f: impl FnOnce(&mut Parser) -> PResult<T>) -> PResult<T> {
        self.layout.push(l);
        let r = f(self);
        // after an error (recovering) a bracket stays open: it shapes where
        // parsing can pick up again
        if r.is_ok() || !self.recovering || !matches!(l, Layout::NoLayout) {
            self.layout.pop();
        }
        r
    }'''
new='''    fn with_layout<T>(&mut self, l: Layout, f: impl FnOnce(&mut Parser) -> PResult<T>) -> PResult<T> {
        let at = self.layout.len();
        self.layout.push(l);
        let r = f(self);
        if r.is_ok() || !self.recovering {
            self.layout.pop();
        } else if at < self.layout.len() {
            // after an error (recovering) a bracket stays open: it shapes
            // where parsing can pick up again (a computation expression's
            // braces too); other layouts go, leaving what opened inside
            match l {
                Layout::NoLayout => {}
                Layout::Block(0) => self.layout[at] = Layout::NoLayout,
                _ => {
                    self.layout.remove(at);
                }
            }
        }
        r
    }'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
