        let mut larms = Vec::new();
        for a in arms {
            for p in or_alternatives(&a.pat) {
                larms.push(LArm { pat: p, guard: a.guard.as_ref(), body: &a.body });
            }
        }
        out.extend(self.ladder_chain(&larms, &subj, &tryfind, simple, dest));
        out
