            out.extend(self.ladder_chain(&arms[1..], subj, tryfind, simple, dest));
            return out;
        }
        let Some(cond) = cond.filter(|_| arms.len() > 1) else { return body };
        let rest = self.ladder_chain(&arms[1..], subj, tryfind, simple, dest);
