            PatKind::Str(t) => conds.push(PE::Cmp(Box::new(subj.clone()), vec![(Cop::Eq, PE::Str(t.clone()))])),
            PatKind::Bool(b) => conds.push(PE::Cmp(Box::new(subj.clone()), vec![(Cop::Is, PE::Bool(*b))])),
