    fn ctor_arg_types(&mut self, c: &CtorInfo, t: &Ty) -> Vec<Ty> {
        let args_t = match t {
            Ty::Con(_, a) => a.clone(),
            _ => vec![],
        };
        let mut inst = Inst::default();
        for (i, a) in args_t.iter().enumerate() {
            inst.t.insert(i, a.clone());
        }
        let mut out = Vec::new();
        for a in &c.args {
            let x = self.st.inst_ty(a, &mut inst);
            out.push(self.st.resolve(&x));
        }
        out
