            let complete = all.iter().all(|(c, _)| present.iter().any(|p| covers(p, c)) || col.iter().any(|p| list_star_covers(p, c)));
            if complete && !all.is_empty() {
                for (c, ats) in all {
                    let spec = specialize(&rows, c);
                    let mut ntys = ats.clone();
                    ntys.extend_from_slice(&tys[1..]);
