fn collect_case_names(p: &Pat, out: &mut Vec<String>) {
    match &p.kind {
        PatKind::Ctor(_, n, _) => out.push(n.clone()),
        PatKind::Or(alts) => alts.iter().for_each(|x| collect_case_names(x, out)),
        _ => {}
    }
}

fn display_ctor(c: &CtorInfo) -> String {
    c.name.clone()
}

fn expand_or(r: &[P], out: &mut Vec<Vec<P>>) {
    if r.is_empty() {
        out.push(vec![]);
        return;
    }
    match &r[0] {
        P::Or(alts) => {
            for a in alts {
                let mut nr = vec![a.clone()];
                nr.extend_from_slice(&r[1..]);
                expand_or(&nr, out);
            }
        }
        _ => out.push(r.to_vec()),
    }
}

fn collect_list_lens(p: &P, maxfixed: &mut i64, maxpre: &mut usize, maxsuf: &mut usize) {
    match p {
        P::List(pre, None) => *maxfixed = (*maxfixed).max(pre.len() as i64),
        P::List(pre, Some(suf)) => {
            *maxpre = (*maxpre).max(pre.len());
            *maxsuf = (*maxsuf).max(suf.len());
        }
        P::Or(alts) => {
            for a in alts {
                collect_list_lens(a, maxfixed, maxpre, maxsuf);
            }
        }
        _ => {}
    }
}

fn present_ctors(col: &[&P]) -> Vec<Ctor> {
    let mut out = Vec::new();
    for p in col {
        match p {
            P::C(c, _) => {
                if !out.contains(c) {
                    out.push(c.clone());
                }
            }
            P::List(pre, None) => {
                let c = Ctor::Len(pre.len());
                if !out.contains(&c) {
                    out.push(c);
                }
            }
            _ => {}
        }
    }
    out
}

fn covers(p: &Ctor, c: &Ctor) -> bool {
    match (p, c) {
        (Ctor::Adt { name: a, tname: ta, .. }, Ctor::Adt { name: b, tname: tb, .. }) => a == b && ta == tb,
        (Ctor::Record { .. }, Ctor::Record { .. }) => true,
        (Ctor::Tuple(_), Ctor::Tuple(_)) => true,
        _ => p == c,
    }
}

/// A star list pattern covers every length it can absorb.
fn list_star_covers(p: &P, c: &Ctor) -> bool {
    match (p, c) {
        (P::List(pre, Some(suf)), Ctor::Len(k)) => pre.len() + suf.len() <= *k,
        (P::List(pre, Some(suf)), Ctor::VarLen(a, b)) => pre.len() + suf.len() <= a + b,
        _ => false,
    }
}

fn specialize(rows: &[Vec<P>], c: &Ctor) -> Vec<Vec<P>> {
    let arity = match c {
        Ctor::Adt { arity, .. } => *arity,
        Ctor::Tuple(n) => *n,
        Ctor::Record { fields, .. } => fields.len(),
        Ctor::Len(k) => *k,
        Ctor::VarLen(a, b) => a + b,
        _ => 0,
    };
    let mut out = Vec::new();
    for r in rows {
        let head = &r[0];
        let rest = &r[1..];
        let sub: Option<Vec<P>> = match head {
            P::Wild => Some(vec![P::Wild; arity]),
            P::C(pc, args) => {
                if covers(pc, c) {
                    Some(args.clone())
                } else {
                    None
                }
            }
            P::List(pre, None) => match c {
                Ctor::Len(k) if pre.len() == *k => Some(pre.clone()),
                _ => None,
            },
            P::List(pre, Some(suf)) => match c {
                Ctor::Len(k) if pre.len() + suf.len() <= *k => {
