new='''            error: None,
            renamed: HashSet::new(),
            module_renames: HashSet::new(),
        }
    }

    /// Work out which nested bindings must not reuse their names.
    pub fn prepare_shadowing(&mut self, decls: &[Decl]) {
        let mut referenced = HashSet::new();
        for (_, d) in &self.ck.ide.uses {
            if let Some(def) = self.ck.ide.defs.get(*d) {
                referenced.insert((def.span.lo, def.span.hi));
            }
        }
        let mut sh = crate::shadow::Shadow { referenced: &referenced, renamed: HashSet::new() };
        sh.program(decls);
        self.renamed = sh.renamed;
    }

    /// Bind a pattern or `let` variable defined at `span`, under a fresh
    /// name when it would overwrite an enclosing variable still in use (an
    /// or-pattern's later alternatives reuse the first one's name).
    pub fn bind_site(&mut self, n: &str, span: crate::source::Span) -> String {
        if !self.renamed.contains(&(span.lo, span.hi)) {
            return self.bind(n, BKind::Value, false);
        }
        if let Some(b) = self.scopes.last().and_then(|s| s.get(n)) {
            if b.py.starts_with('_') {
                return b.py.clone();
            }
        }
        let base = format!("_{}", mangle(n));
        let mut k = 1;
        let py = loop {
            let cand = if k == 1 { base.clone() } else { format!("{}{}", base, k) };
            let used = self.top_binds.keys().any(|t| mangle(t) == cand)
                || self.scopes.iter().any(|s| s.values().any(|b| b.py == cand))
                || match self.fn_stack.last() {
                    Some(f) => f.renames.contains(&cand),
                    None => self.module_renames.contains(&cand),
                };
            if !used {
                break cand;
            }
            k += 1;
        };
        match self.fn_stack.last_mut() {
            Some(f) => {
                f.renames.insert(py.clone());
            }
            None => {
                self.module_renames.insert(py.clone());
            }
        }
        let depth = self.depth();
        self.scopes.last_mut().unwrap().insert(n.to_string(), Bind { py: py.clone(), kind: BKind::Value, mutable: false, depth });
        py
    }
