p='/workspace/src/lower2.rs'
s=open(p).read()
old='''        // a match whose value is dropped runs its arms for their effects
        if let (true, ExprKind::Match(s, arms)) = (self.native, &e.kind) {
            return self.match_stmt(s, arms, e.span, &Dest::Discard);
        }'''
new='''        // a match whose value is dropped: a ladder runs its arms for their
        // effects alone
        if let (true, ExprKind::Match(s, arms)) = (self.native, &e.kind) {
            let t = self.new_tmp();
            let mut out = self.match_stmt(s, arms, e.span, &Dest::Assign(t.clone()));
            if matches!(out.last(), Some(PS::If(..))) {
                for st in out.iter_mut() {
                    if let PS::If(..) = st {
                        drop_assign(st, &t);
                    }
                }
            } else {
                out.push(PS::Expr(name(&t)));
            }
            return out;
        }'''
assert old in s
s=s.replace(old,new)
s=s.rstrip('\n')+'''

/// Inside a ladder, `t = value` becomes the bare `value`.
fn drop_assign(st: &mut PS, t: &str) {
    match st {
        PS::If(arms, els) => {
            for (_, body) in arms.iter_mut() {
                for x in body.iter_mut() {
                    drop_assign(x, t);
                }
            }
            if let Some(body) = els {
                for x in body.iter_mut() {
                    drop_assign(x, t);
                }
            }
        }
        PS::Assign(PE::Name(n), v) if n == t => *st = PS::Expr(v.clone()),
        _ => {}
    }
}
'''
open(p,'w').write(s)
