                let mut sites = Vec::new();
                inner_sites(e, &mut sites);
                out.extend(sites.into_iter().map(|(n, _)| crate::lower::mangle(&n)));
            }
            Decl::Module(_, _, ds) => module_bound(ds, out),
            _ => {}
        }
    }
}

