#!/usr/bin/env python3
# typed random program generator: well-typed programs over a small set of types; compare outputs
import random, subprocess, sys, os
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
N = int(sys.argv[2]) if len(sys.argv) > 2 else 100
MODES = sys.argv[3].split(',') if len(sys.argv) > 3 else ['compile', 'compile --native', 'run']
random.seed(seed)
PRE = '''type Shape =
  | Circle int
  | Rect int int
  | Dot
type R = { a: int, b: string }
'''
class G:
    def __init__(self):
        self.n = 0
    def fresh(self):
        self.n += 1
        return f'v{self.n}'
    def var(self, env, t):
        c = [v for v, vt in env if vt == t]
        return random.choice(c) if c else None
    def ind(self, s, k):
        return s.replace('\n', '\n' + ' ' * k)
    def e(self, t, env, d):
        if d > 3:
            return self.leaf(t, env)
        k = random.random()
        if k < 0.12:
            # block
            v = self.fresh()
            vt = random.choice(['int', 'string', 'intlist'])
            val = self.e(vt, env, d + 1)
            body = self.e(t, env + [(v, vt)], d + 1)
            return f'(\n  let {v} = {self.ind(val, 2)}\n  {self.ind(body, 2)})'
        if k < 0.22:
            c = self.e('bool', env, d + 1)
            return f'(if {c} then {self.e(t, env, d + 1)} else {self.e(t, env, d + 1)})'
        if k < 0.34:
            return self.match(t, env, d)
        return self.form(t, env, d)
    def leaf(self, t, env):
        v = self.var(env, t)
        if v and random.random() < 0.6:
            return v
        return {'int': str(random.randint(0, 9)), 'string': random.choice(['"a"', '"bc"', '""']), 'bool': random.choice(['true', 'false']),
                'intlist': random.choice(['[]', '[1, 2]', '[3]']), 'intopt': random.choice(['None', 'Some 1']), 'shape': random.choice(['Dot', 'Circle 2', 'Rect 1 2']),
                'rec': 'R { a = 1, b = "x" }', 'pair': '(1, "p")'}[t]
    def match(self, t, env, d):
        st = random.choice(['int', 'intopt', 'shape', 'intlist', 'pair', 'rec'])
        s = self.e(st, env, d + 1)
        arms = []
        if st == 'int':
            arms.append(('0', []))
            v = self.fresh(); arms.append((v, [(v, 'int')]))
        elif st == 'intopt':
            v = self.fresh(); arms.append((f'Some {v}', [(v, 'int')])); arms.append(('None', []))
        elif st == 'shape':
            v = self.fresh(); arms.append((f'Circle {v}', [(v, 'int')]))
            w = self.fresh(); arms.append((f'Rect {w} _', [(w, 'int')]))
            arms.append(('_', []))
        elif st == 'intlist':
            arms.append(('[]', []))
            h = self.fresh(); r = self.fresh(); arms.append((f'[{h}, *{r}]', [(h, 'int'), (r, 'intlist')]))
        elif st == 'pair':
            a = self.fresh(); b = self.fresh(); arms.append((f'({a}, {b})', [(a, 'int'), (b, 'string')]))
        else:
            arms.append(('R { a = 0 }', []))
            a = self.fresh(); arms.append((f'R {{ a = {a}, b }}', [(a, 'int'), ('b', 'string')]))
        out = f'(match {s}:'
        for p, binds in arms:
            g = ''
            if random.random() < 0.15:
                g = f' if {self.e("bool", env + binds, d + 2)}'
            body = self.e(t, env + binds, d + 1)
            out += f'\n  case {p}{g}: {self.ind(body, 4)}'
        if 'if' in out and '_' not in [p for p, _ in arms]:
            out += f'\n  case _: {self.leaf(t, env)}'
        return out + ')'
    def form(self, t, env, d):
        e = lambda tt: self.e(tt, env, d + 1)
        if t == 'int':
            return random.choice([
                lambda: f'{e("int")} + {e("int")}', lambda: f'{e("int")} * {e("int")}', lambda: f'List.len {e("intlist")}',
                lambda: f'List.sum {e("intlist")}', lambda: f'String.len {e("string")}', lambda: f'(fun x -> x + {e("int")}) {e("int")}',
                lambda: f'{e("intlist")} |> List.map (fun x -> x * 2) |> List.sum', lambda: f'{e("rec")}.a',
                lambda: f'List.fold (fun acc x -> acc + x) 0 {e("intlist")}', lambda: f'Option.defaultValue 0 {e("intopt")}',
                lambda: self.leaf(t, env)])()
        if t == 'string':
            return random.choice([lambda: f'f"<{{{e("int")}}}>"', lambda: f'String.concat {e("string")} {e("string")}', lambda: f'String.upper {e("string")}',
                                  lambda: f'String.fromInt {e("int")}', lambda: f'{e("rec")}.b', lambda: f'String.join "," (List.map String.fromInt {e("intlist")})',
                                  lambda: self.leaf(t, env)])()
        if t == 'bool':
            return random.choice([lambda: f'{e("int")} > {e("int")}', lambda: f'{e("int")} == {e("int")}', lambda: f'not ({e("bool")})',
                                  lambda: f'{e("bool")} and {e("bool")}', lambda: f'List.isEmpty {e("intlist")}', lambda: f'List.contains {e("int")} {e("intlist")}',
                                  lambda: f'Option.isSome {e("intopt")}', lambda: self.leaf(t, env)])()
        if t == 'intlist':
            return random.choice([lambda: f'[{e("int")}, {e("int")}]', lambda: f'List.map (fun x -> x + {e("int")}) {e("intlist")}',
                                  lambda: f'List.filter (fun x -> x > {e("int")}) {e("intlist")}', lambda: f'List.rev {e("intlist")}',
                                  lambda: f'List.range 0 {e("int")}', lambda: self.leaf(t, env)])()
        if t == 'intopt':
            return random.choice([lambda: f'Some {e("int")}', lambda: f'List.find (fun x -> x > {e("int")}) {e("intlist")}', lambda: f'List.head {e("intlist")}',
                                  lambda: f'Option.map (fun x -> x + 1) {e("intopt")}', lambda: self.leaf(t, env)])()
        if t == 'shape':
            return random.choice([lambda: f'Circle {e("int")}', lambda: f'Rect {e("int")} {e("int")}', lambda: 'Dot'])()
        if t == 'rec':
            return random.choice([lambda: f'R {{ a = {e("int")}, b = {e("string")} }}', lambda: f'{{ {e("rec")} with a = {e("int")} }}'])()
        if t == 'pair':
            return f'({e("int")}, {e("string")})'
    def program(self):
        out = [PRE]
        env = []
        for i in range(random.randint(1, 3)):
            v = self.fresh()
            t = random.choice(['int', 'string', 'intlist', 'bool'])
            if random.random() < 0.5:
                p = self.fresh(); pt = random.choice(['int', 'string'])
                body = self.e(t, env + [(p, pt)], 0)
                out.append(f'let {v} ({p}: {pt if pt != "intlist" else "List int"}) =\n  {self.ind(body, 2)}')
                arg = self.leaf(pt, env)
                out.append(f'print ({v} {arg})')
            else:
                out.append(f'let {v} =\n  {self.ind(self.e(t, env, 0), 2)}')
                env.append((v, t))
                out.append(f'print {v}')
        return '\n'.join(out) + '\n'
os.makedirs('/tmp/pf/tgfz', exist_ok=True)
same = diff = 0
for i in range(N):
    src = G().program()
    f = f'/tmp/pf/tgfz/t{seed}_{i}.pyfun'
    open(f, 'w').write(src)
    bad = False
    for mode in MODES:
        r = []
        for exe in ('/tmp/pf/orig/pyfun', '/workspace/target/release/pyfun'):
            try:
                p = subprocess.run([exe] + mode.split() + [os.path.basename(f)], cwd='/tmp/pf/tgfz', capture_output=True, timeout=30)
                out = p.stdout.replace(b'pyfun_run_', b'X')
                import re
                out = re.sub(rb'pyfun_run_\d+', b'R', p.stdout); err = re.sub(rb'pyfun_run_\d+', b'R', p.stderr)
                r.append((out, err, p.returncode))
            except subprocess.TimeoutExpired:
                r.append(('TIMEOUT',))
        if r[0] != r[1]:
            bad = True
            print(f'DIFF {f} {mode}')
            break
    if bad: diff += 1
    else:
        same += 1
        os.remove(f)
print(f'{same}/{same+diff} same')
