#!/usr/bin/env python3
# usage: kfuzz.py files...  -- split each source into cells at blank lines, run kernel-engine eval for each, compare
import subprocess, sys
def cells(src):
    out, cur = [], []
    for l in src.split('\n'):
        if l.strip() == '' and cur and not (l.startswith(' ')):
            out.append('\n'.join(cur)); cur = []
        elif l.strip() != '' or cur:
            cur.append(l)
    if cur: out.append('\n'.join(cur))
    return out
def run(exe, cs):
    data = b''
    for c in cs:
        for part in ('eval', c):
            b = part.encode(); data += b'%08d' % len(b) + b
    for part in ('type', '1'):
        b = part.encode(); data += b'%08d' % len(b) + b
    p = subprocess.run([exe, 'kernel-engine'], input=data, capture_output=True, timeout=60)
    return p.stdout, p.stderr, p.returncode
bad = 0
for f in sys.argv[1:]:
    cs = cells(open(f).read())
    a = run('/tmp/pf/orig/pyfun', cs); b = run('/workspace/target/release/pyfun', cs)
    if a != b:
        bad += 1
        print('=== DIFF', f)
        import difflib
        x = a[0].decode(errors='replace').split('\n'); y = b[0].decode(errors='replace').split('\n')
#!/usr/bin/env python3
# usage: replfuzz.py files...  -- turn each source into a REPL session (multi-line decls in :{ :}), compare orig vs mine
import subprocess, sys, os
def session(src):
    lines = src.split('\n')
    decls = []
    cur = []
    for l in lines:
        if l and not l[0].isspace() and not l.startswith('#') and cur:
            decls.append(cur); cur = []
        if l.strip() == '' and not cur:
            continue
        cur.append(l)
    if cur: decls.append(cur)
    out = []
    for d in decls:
        while d and d[-1].strip() == '':
            d.pop()
        body = [x for x in d if not x.strip().startswith('#')]
        if not body: continue
        if len(body) == 1:
            out.append(body[0])
        else:
            out.append(':{'); out.extend(body); out.append(':}')
    out.append(':type 1')
    return '\n'.join(out) + '\n'
bad = 0
for f in sys.argv[1:]:
    inp = session(open(f).read())
    r = []

