#!/usr/bin/env python3
# random multi-module projects: cross-module types/values/functions, name clashes; compare check/compile/native/run
import random, subprocess, sys, os, shutil, re
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
N = int(sys.argv[2]) if len(sys.argv) > 2 else 50
random.seed(seed)
def mod_a():
    lines = []
    if random.random() < 0.6:
        lines.append('type Shape =\n  | Circle int\n  | Sq int\n  | Dot')
    if random.random() < 0.5:
        lines.append('type Pt = { x: int, y: int }')
    lines.append('let area s =\n  match s:\n    case Circle r: r * r * 3\n    case Sq n: n * n\n    case Dot: 0' if 'type Shape' in '\n'.join(lines) else 'let area n = n * n')
    lines.append(random.choice(['let scale k n = k * n', 'let scale k n = n + k']))
    if random.random() < 0.4:
        lines.append('let origin = Pt { x = 0, y = 0 }' if 'type Pt' in '\n'.join(lines) else 'let origin = (0, 0)')
    if random.random() < 0.4:
        lines.append('let lookup k =\n  if k == 1 then Some 10 else None')
    if random.random() < 0.3:
        lines.append(random.choice(['let b = 5', 'let main = 3', 'let geo = 1']))
    return '\n'.join(lines) + '\n'
def mod_main(a_src, a_name, b_used):
    lines = [f'import {a_name}']
    if b_used:
        lines.append('import Util')
    has_shape = 'type Shape' in a_src
    if has_shape:
        lines.append(f'print ({a_name}.area ({a_name}.Circle 2))')
        if random.random() < 0.5:
            lines.append(f'let f s =\n  match s:\n    case {a_name}.Sq n: n\n    case _: 0\nprint (f ({a_name}.Sq 4))')
    else:
        lines.append(f'print ({a_name}.area 3)')
    if random.random() < 0.5:
        lines.append(f'let w = {a_name}.scale 2')
        lines.append('print (w 5)')
    if 'lookup' in a_src:
        lines.append(f'print ({a_name}.lookup 1 |> Option.withDefault 0)')
    if 'origin = Pt' in a_src:
        lines.append(f'let p = {{ {a_name}.origin with x = 3 }}')
        lines.append('print p.x')
    if random.random() < 0.3:
        lines.append(random.choice([f'let {a_name.lower()} = 7\nprint {a_name.lower()}', 'let util = 2\nprint util']))
    if b_used:
        lines.append('print (Util.twice 4)')
    return '\n'.join(lines) + '\n'
same = diff = 0
for i in range(N):
    d = f'/tmp/pf/prfz/p{seed}_{i}'
    shutil.rmtree(d, ignore_errors=True); os.makedirs(d)
    a_name = random.choice(['Geo', 'Shapes', 'Lib'])
    a_src = mod_a()
    open(f'{d}/{a_name.lower()}.pyfun', 'w').write(a_src)
    b_used = random.random() < 0.4
    if b_used:
        imp = f'import {a_name}\n' if random.random() < 0.5 else ''
        open(f'{d}/util.pyfun', 'w').write(imp + 'let twice n = n * 2\n')
    open(f'{d}/main.pyfun', 'w').write(mod_main(a_src, a_name, b_used))
    bad = False
    for mode in (['check'], ['compile'], ['compile', '--native'], ['run']):
        r = []
        for exe in ('/tmp/pf/orig/pyfun', '/workspace/target/release/pyfun'):
            p = subprocess.run([exe] + mode + ['main.pyfun'], cwd=d, capture_output=True, timeout=30)
            out = re.sub(rb'pyfun_run_\d+', b'R', p.stdout); err = re.sub(rb'pyfun_run_\d+', b'R', p.stderr)
            r.append((out, err, p.returncode))
        if r[0] != r[1]:
            bad = True
            print('DIFF', d, ' '.join(mode))
            break
    if bad: diff += 1
    else:
        same += 1
        shutil.rmtree(d)
print(f'{same}/{same+diff} same')
EOF
