            let e = self.ce_expr(item_col, line, kw)?;
            Ok(CeStmt::LetBang(pat, e, t.span))
        }
        Tok::Let => {
            let col = self.raw_at(0).col;
            let _ = col;
            let l = self.with_layout(Layout::CeItem { item_col, expr_col: usize::MAX, line, kw }, |p| p.let_decl_ce(item_col, line))?;
