                self.bump();
                let e = self.ce_expr(item_col, line, kw)?;
                return Ok(CeStmt::ReturnBang(e, t.span));
            }
            let e = self.ce_expr(item_col, line, kw)?;
            Ok(CeStmt::Return(e, t.span))
        }
