            self.bump();
            if self.raw().tok == Tok::Bang {
                self.bump();
                let e = self.ce_expr(item_col, line, kw)?;
                return Ok(CeStmt::YieldBang(e, t.span));
            }
            let e = self.ce_expr(item_col, line, kw)?;
            Ok(CeStmt::Yield(e, t.span))
        }
