            Ok(CeStmt::Let(LetDecl {
                pat: Pat { kind: PatKind::Wild, span: Span::new(span.lo, span.lo) },
                params: Vec::new(),
                mutable: false,
                pure_: false,
                value: e,
                doc: None,
                name_span: Span::new(span.lo, span.lo),
                span,
                active: None,
                case_spans: Vec::new(),
