            // the expression starts on its own line: an indented block
            return self.with_layout(Layout::Block(item_col), |p| p.body());
        }
        let expr_col = t.col;
        // the item's expression may start on the next line, wherever it stands
        self.anchor = t.span.lo;
        self.with_layout(Layout::CeItem { item_col, expr_col, line, kw }, |p| p.expr())
    }'''
