    match r:
      case 1: print "a"
     case _: print "b"
    return ()
  }
'; w f3 'let f r =
  async {
    match r:
      case 1: print "a"
         case _: print "b"
    return ()
  }
'; w f4 'let f r =
  async {
    match r:
      case 1:
        print "a"
         case _: print "b"
    return ()
  }
'; w f5 'let f r =
  async {
    let x = 1  return x
  }
'; w f6 'let f r =
  seq {
    for x in [1]:
      let y = x      yield y
    yield 100
  }
'; for f in f1 f2 f3 f4 f5 f6; do for exe in ./orig/pyfun /workspace/target/release/pyfun; do echo "== $exe $f"; $exe check lay/$f.pyfun 2>&1 | head -2; done; done

