    }

    fn ord_walk(&mut self, t: &Ty, seen: &mut HashSet<String>) -> Result<(), UErr> {
        match self.st.shallow(t) {
            Ty::Var(w) => {
                self.st.tord[w] = true;
                Ok(())
            }
            Ty::Fun(..) => Err(UErr::NotOrdered(self.st.resolve(t))),
