                    Some(TypeDef::Record(fs)) => fs.into_iter().map(|(_, ft)| ft).collect(),
                    Some(TypeDef::Adt(cs)) => cs
                        .iter()
                        .filter_map(|c| self.ctors.values().find(|ci| &ci.type_name == &n && &ci.name == c))

