                            done = unguarded;
                        }
                    }
                }
            }
            match &flag {
                Some(f) => out.push(PS::If(vec![(PE::Not(Box::new(name(f))), block)], None)),
                None => out.extend(block),
            }
            // (with a flag every arm is written out)
            if done && returns {
