    pub fn check_top_lets(&mut self, members: &[&LetDecl], _decls: &[Decl], _at: usize) {
        if members.len() == 1 {
            let l = members[0];
            self.effs.push(EffAcc::default());
            let r = self.check_one_top_let(l);
            let acc = self.effs.pop().unwrap();
            match r {
                Ok(t) => {
                    if let Err(d) = self.check_pure(l, &t, &acc) {
                        self.errors.push(d);
